export function countRowsForIssue(db: DB, issueNumber: number, sinceIso: string): number {
  const row = db
    .prepare(
      `SELECT COUNT(*) AS n FROM enrich_failures
        WHERE issue_number = ? AND reviewed_at > ?`,
    )
    .get(issueNumber, sinceIso) as { n: number };
  return row.n;
}

